import * as T from './vendor/three.module.js';
// Bake immutable architecture by material. Characters, movable gates, carts and lids stay separate.
export function batchArchitecture(root){root.updateMatrixWorld(true);const inverse=new T.Matrix4().copy(root.matrixWorld).invert(),groups=new Map();root.traverse(o=>{if(!o.isMesh||o.isInstancedMesh||!o.userData.static||Array.isArray(o.material)||o.material.transparent)return;for(let p=o;p&&p!==root;p=p.parent)if(p.userData.dynamic)return;const list=groups.get(o.material)||[];list.push(o);groups.set(o.material,list)});let count=0;for(const [material,meshes] of groups){if(meshes.length<3)continue;const parts=meshes.map(o=>{let g=o.geometry.clone();if(g.index){const flat=g.toNonIndexed();g.dispose();g=flat}g.applyMatrix4(new T.Matrix4().multiplyMatrices(inverse,o.matrixWorld));return g}),size=parts.reduce((n,g)=>n+g.attributes.position.count,0),geometry=new T.BufferGeometry();for(const [name,width] of [['position',3],['normal',3],['uv',2]]){const data=new Float32Array(size*width);let offset=0;for(const g of parts){if(g.attributes[name])data.set(g.attributes[name].array,offset);offset+=g.attributes.position.count*width}geometry.setAttribute(name,new T.BufferAttribute(data,width))}geometry.computeBoundingSphere();const mesh=new T.Mesh(geometry,material);mesh.name='architecture-batch';root.add(mesh);for(const o of meshes){o.removeFromParent();o.geometry.dispose()}for(const g of parts)g.dispose();count++}return count}
